// real file/folder logos (vscode-icons subset, generated by scripts/build-icons.mjs)
import data from "./file-icons.json";

type Icon = { body: string; w: number; h: number };
const icons = data.icons as Record<string, Icon>;
const names = data.names as Record<string, string>;
const exts = data.exts as Record<string, string>;
const folders = data.folders as Record<string, [string, string]>;

function fileIconName(path: string) {
	const base = path.split("/").pop()!.toLowerCase();
	if (names[base]) return names[base];
	if (base.startsWith(".env")) return names[".env"];
	// longest extension first: "next-env.d.ts" tries "env.d.ts", "d.ts", then "ts"
	const parts = base.split(".");
	for (let i = 1; i < parts.length; i++) {
		const ext = parts.slice(i).join(".");
		if (exts[ext]) return exts[ext];
	}
	return data.file;
}

function Svg({ name, size }: { name: string; size: number }) {
	const i = icons[name];
	// bodies come from our own build-time JSON (MIT icon set), never from the repo being browsed
	return <svg className="ficon" width={size} height={size} viewBox={`0 0 ${i.w} ${i.h}`} dangerouslySetInnerHTML={{ __html: i.body }} />;
}

export function FileIcon({ path, size = 15 }: { path: string; size?: number }) {
	return <Svg name={fileIconName(path)} size={size} />;
}

export function FolderIcon({ name, open, size = 15 }: { name: string; open: boolean; size?: number }) {
	const pair = folders[name.toLowerCase()] ?? data.folder;
	return <Svg name={pair[open ? 1 : 0]} size={size} />;
}
